"""Writes render_psd_mango.jsx from layers/manifest.json (layer order and names) and the character geometry."""
import json
from pathlib import Path

import mango_char as ch

HERE = Path(__file__).parent
PSD_NAME = "artwork"  # Photoshop document name; rename per project

JSX = r"""// Mango PFP: assemble the layered PSD from ai_draw.py layer exports, then add light passes as separate named layers.
// No blur on any scenery layer (skill rule 12); blur is used only on light layers (rim, glow).
// Generated by gen_psd_jsx.py. Run: cli-anything-photoshop --json script run --file render_psd_mango.jsx
(function () {
  var dir = '%DIR%';
  var files = [
%FILES%
  ];
  function c(s) { return charIDToTypeID(s); }
  function rgb(hex) { var k = new SolidColor(); k.rgb.hexValue = hex.replace('#', ''); return k; }
  function ellipse(cx, cy, rx, ry) { var p = []; for (var i = 0; i < 72; i++) { var t = i / 72 * 2 * Math.PI; p.push([cx + Math.cos(t) * rx, cy + Math.sin(t) * ry]); } return p; }
  function loadAlpha(layer) {
    doc.activeLayer = layer;
    var d = new ActionDescriptor(), r = new ActionReference(); r.putProperty(c('Chnl'), c('fsel')); d.putReference(c('null'), r);
    var r2 = new ActionReference(); r2.putEnumerated(c('Chnl'), c('Chnl'), c('Trsp')); d.putReference(c('T   '), r2);
    executeAction(c('setd'), d, DialogModes.NO);
  }
  function maskFromSelection(layer) {
    doc.activeLayer = layer;
    var d = new ActionDescriptor(); d.putClass(c('Nw  '), c('Chnl'));
    var r = new ActionReference(); r.putEnumerated(c('Chnl'), c('Chnl'), c('Msk ')); d.putReference(c('At  '), r);
    d.putEnumerated(c('Usng'), c('UsrM'), c('RvlS')); executeAction(c('Mk  '), d, DialogModes.NO);
  }
  function newLayer(name, blend, opacity) { var l = doc.artLayers.add(); l.name = name; l.blendMode = blend; l.opacity = opacity; return l; }
  function paint(layer, pts, feather, hex) {
    doc.activeLayer = layer; doc.selection.select(pts); if (feather) doc.selection.feather(feather);
    doc.selection.fill(rgb(hex)); doc.selection.deselect();
  }

  // free scratch space: close my own already-saved PSD from the previous job (never the user's unsaved documents)
  for (var q = app.documents.length - 1; q >= 0; q--) { var od = app.documents[q]; if (od.name == '%NAME%.psd' && od.saved) od.close(SaveOptions.DONOTSAVECHANGES); }

  app.preferences.rulerUnits = Units.PIXELS;
  var doc = app.documents.add(2000, 2000, 72, '%NAME%', NewDocumentMode.RGB, DocumentFill.TRANSPARENT);
  var base = doc.artLayers[0];
  var groups = {}, L = {};
  for (var i = 0; i < files.length; i++) {
    var src = app.open(new File(dir + files[i][2]));
    var dup = src.activeLayer.duplicate(doc, ElementPlacement.PLACEATBEGINNING);
    src.close(SaveOptions.DONOTSAVECHANGES);
    app.activeDocument = doc;
    dup.name = files[i][1];
    var g = files[i][0];
    if (!groups[g]) { groups[g] = doc.layerSets.add(); groups[g].name = g; groups[g].move(dup, ElementPlacement.PLACEBEFORE); }
    dup.move(groups[g], ElementPlacement.PLACEATBEGINNING);
    L[files[i][1]] = dup;
  }
  base.remove();

  // --- sun bloom: glow on the light source itself, under the scenery in front of it ---
  var bloom = newLayer('Sun bloom', BlendMode.SCREEN, 45); bloom.move(L['Sun'], ElementPlacement.PLACEBEFORE);
  paint(bloom, ellipse(%SX%, %SY%, 430, 430), 240, '#ffcf7a');

  // --- character light, masked to Mango's silhouette ---
  var mango = groups['Mango'];
  var tmp = mango.duplicate(); tmp = tmp.merge(); tmp.name = 'tmp alpha';
  var light = doc.layerSets.add(); light.name = 'Lighting'; light.move(mango, ElementPlacement.PLACEBEFORE);
  function lightLayer(name, blend, opacity) { var l = newLayer(name, blend, opacity); l.move(light, ElementPlacement.PLACEATEND); return l; }
  var shade = lightLayer('Form shade', BlendMode.MULTIPLY, 40);
  paint(shade, ellipse(700, 1420, 420, 260), 220, '#5a2040');
  var fill = lightLayer('Warm face fill', BlendMode.SOFTLIGHT, 55);
  paint(fill, ellipse(%FX%, %FY%, 400, 330), 220, '#ffe0a8');
  var rim = lightLayer('Sun rim', BlendMode.SCREEN, 85);
  loadAlpha(tmp); doc.activeLayer = rim; doc.selection.fill(rgb('#ffd27a'));
  loadAlpha(tmp); doc.selection.translate(-12, 7); doc.activeLayer = rim; doc.selection.clear(); doc.selection.deselect();
  rim.applyGaussianBlur(2.5);
  var lights = [shade, fill, rim];
  for (var k = 0; k < lights.length; k++) { loadAlpha(tmp); maskFromSelection(lights[k]); }
  doc.selection.deselect();
  tmp.remove();

  // --- glow, grade, finish ---
  var fxg = groups['FX'];
  function topLayer(name, blend, opacity) { var l = newLayer(name, blend, opacity); l.move(fxg, ElementPlacement.PLACEBEFORE); return l; }
  var led = topLayer('Controller LED glow', BlendMode.SCREEN, 60);
  paint(led, ellipse(%LX%, %LY%, 70, 34), 30, '#ff9a2a');
  var grade = topLayer('Colour grade', BlendMode.SOFTLIGHT, 16);
  doc.activeLayer = grade; doc.selection.selectAll(); doc.selection.fill(rgb('#ff8a3a')); doc.selection.deselect();
  var vig = topLayer('Vignette', BlendMode.MULTIPLY, 40);
  doc.activeLayer = vig; doc.selection.selectAll(); doc.selection.fill(rgb('#1a0c20'));
  doc.selection.select(ellipse(1000, 1000, 1060, 1060)); doc.selection.feather(300); doc.selection.clear(); doc.selection.deselect();
  var grain = topLayer('Grain', BlendMode.OVERLAY, 12);
  doc.activeLayer = grain; doc.selection.selectAll(); doc.selection.fill(rgb('#808080')); doc.selection.deselect();
  grain.applyAddNoise(3, NoiseDistribution.GAUSSIAN, true);

  var out = [];
  for (var n = 0; n < doc.layers.length; n++) {
    var Ly = doc.layers[n], t = Ly.name;
    if (Ly.typename == 'LayerSet') { var chn = []; for (var j = 0; j < Ly.layers.length; j++) chn.push(Ly.layers[j].name); t += ' {' + chn.join(', ') + '}'; }
    out.push(t);
  }
  return out.join(' | ');
})();
"""


def main():
    import mango_bg as bg
    man = json.loads((HERE / "layers" / "manifest.json").read_text(encoding="utf-8"))
    rows = []
    for lay in man["layers"]:
        g, n = lay["path"].split("/", 1)
        rows.append(f"    ['{g}', '{n}', '{Path(lay['file']).name}']")
    led, face = ch.C(0, -22), ch.M(0, 80)
    out = (JSX.replace("%FILES%", ",\n".join(rows))
           .replace("%LX%", f"{led[0]:.0f}").replace("%LY%", f"{led[1]:.0f}")
           .replace("%FX%", f"{face[0]:.0f}").replace("%FY%", f"{face[1]:.0f}")
           .replace("%SX%", f"{bg.SUN[0]}").replace("%SY%", f"{bg.SUN[1]}")
           .replace("%DIR%", (HERE / "layers").resolve().as_posix() + "/").replace("%NAME%", PSD_NAME))
    (HERE / "render_psd_mango.jsx").write_text(out, encoding="utf-8")
    print(f"wrote render_psd_mango.jsx: {len(rows)} layers, LED {led[0]:.0f},{led[1]:.0f}, face {face[0]:.0f},{face[1]:.0f}")


if __name__ == "__main__":
    main()
